-- 55_DMF0072_popup_meta_Verify.sql

SELECT 'V1: API_M (2 expected)' AS K, COUNT(*) AS V, CASE WHEN COUNT(*)=2 THEN 'PASS' ELSE 'FAIL' END AS VERDICT FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID IN ('P_DMF0072_PROJECT_POPUP_GET','P_DMF0072_ITEM_POPUP_GET');
SELECT 'V2: BTN_MPG (2 expected)' AS K, COUNT(*) AS V, CASE WHEN COUNT(*)=2 THEN 'PASS' ELSE 'FAIL' END AS VERDICT FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M WHERE MNU_ID='DMF0072' AND SHT_NM IN ('projectPopup','itemPopup');
SELECT 'V3: PROC_M PROJECT (7)' AS K, COUNT(*) AS V, CASE WHEN COUNT(*)=7 THEN 'PASS' ELSE 'FAIL' END AS VERDICT FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM='DMF0072_GET_PROJECT_POPUP_LIST';
SELECT 'V4: PROC_M ITEM (8)' AS K, COUNT(*) AS V, CASE WHEN COUNT(*)=8 THEN 'PASS' ELSE 'FAIL' END AS VERDICT FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM='DMF0072_GET_ITEM_POPUP_LIST';
SELECT 'V5: GUEST popup perm (2)' AS K, COUNT(*) AS V, CASE WHEN COUNT(*)=2 THEN 'PASS' ELSE 'FAIL' END AS VERDICT FROM SCM_MGR.SCM_ADM_USER_GR_MNU_BTN_MPG_M WHERE USER_GR_ID='GUEST' AND MNU_ID='DMF0072' AND SHT_NM IN ('projectPopup','itemPopup');
SELECT 'V6: SP VALID' AS K, COUNT(*) AS V, CASE WHEN COUNT(*)=2 THEN 'PASS' ELSE 'FAIL' END AS VERDICT FROM ALL_OBJECTS WHERE OWNER='SCM_MGR' AND OBJECT_NAME IN ('DMF0072_GET_PROJECT_POPUP_LIST','DMF0072_GET_ITEM_POPUP_LIST') AND OBJECT_TYPE='PROCEDURE' AND STATUS='VALID';
